contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address spender, uint256 amount) public {
        require(spender != address(0));
        bool ok = c.approve(spender, amount); if (__ESBMC_reverted()) return;
        assert(ok && c.allowance(address(this), spender) == amount);
    }
    receive() external payable {}
}

