// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address spender, uint256 amount) internal {
        vm.assume(spender != address(0));
        bool ok;
        try c.approve(spender, amount) returns (bool __r) { ok = __r; } catch { return; }
        assertTrue(ok && c.allowance(address(this), spender) == amount);
    }

    function testFuzz_run(address spender, uint256 amount) public {
        vm.assume(spender.code.length == 0 && uint160(spender) > 0xffff && spender != address(this) && spender != address(c) && spender != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && spender != 0x000000000000000000636F6e736F6c652e6c6f67 && spender != 0x4e59b44847b379578588920cA78FbF26c0B4956C && spender != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(spender, amount);
    }

    receive() external payable {}
}
